import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P06-data_analysis/P06-0-0-Basic-Data-Thinking-Course/02-ruhe-peiyang-shuju-mingandu.html","title":"02-转型：如何培养数据敏感度？","lang":"zh-CN","frontmatter":{"title":"02-转型：如何培养数据敏感度？","icon":"blog","date":"2025-08-04T19:40:35.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"copy":{"disableCopy":true,"disableSelection":true},"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1759189688000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":36,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"e46477f46ba929ad6d616f0d14d6360ef5c1f744","time":1759189688000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 禁用文档复制和选择功能"},{"hash":"f5cbdf105f8b7b38070273e5981d406a9ef5224b","time":1755401142000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据思维课程文档格式和强调内容"},{"hash":"55d0e620935a8cfa2e2ce5f039e99f9a7331de6b","time":1755390034000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 修正文档中标题层级错误"},{"hash":"232ff60dc2258ce371e3f7314e92676332cbce75","time":1755351801000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据敏感度培养方法和课程结束语"},{"hash":"dce2a25fc1c21ff2efc9d494d252dd50bdbcde44","time":1755351066000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 修正文档中数字格式和空格使用"},{"hash":"2b2c3ee4defe4ca9ca4a722bb9150fecf2662df3","time":1755350394000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 在数据敏感性文档中添加关于离婚率的补充说明"},{"hash":"309de7326bfe24b5dd819ab46e3a76b74475925a","time":1755349978000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 修正文档中数字与中文之间的空格格式"},{"hash":"4b00c446692a7d7b8309dd83468d7088e25058d4","time":1754917681000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 在数据思维课程文档中添加强调语句"},{"hash":"30fa702c53e6cce587eaa7b19f0f18ad1c31a7da","time":1754916587000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 修正文档中的标点格式错误"},{"hash":"fa926402d7a6eb2d01b2321090fb11e6ec3df7fb","time":1754916184000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 修正文档中的标点格式和补充说明"},{"hash":"4527f06f4d9500b1a525414f4f64636a0fc95f3a","time":1754915947000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 修正文档中的标点格式和示例人名"},{"hash":"b326a0c7388be25b42195dce0463291ab42439b7","time":1754914952000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据敏感性培养文档中的示例说明"},{"hash":"ffabf8e9aaa7fae333578379ece7b2e92cc694e5","time":1754914656000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"比如："},{"hash":"6241dd16378b9d7115228eb02d00f30c0842d3ce","time":1754913876000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(Python-Programming-Course): 完善数据敏感性课程文档内容"},{"hash":"35f716121250e8cfbf8912680ed2daeec2bebf2d","time":1754825130000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 在数据敏感度文档中添加量转型说明段落"},{"hash":"4225b13650beb98efb677e01ce7c629129d804e6","time":1754824932000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据敏感度培养文档内容"},{"hash":"6abc8b874b2ef3bf3cf207ed0ba4291ea27fa5c8","time":1754798190000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据敏感性文档中的标点和格式"},{"hash":"449153172d3ba4633d973e9e9ff1cfca33cca838","time":1754797334000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 调整文档中强调文本的间距格式"},{"hash":"5f999e223b0e922bdaf9e97c1c8854dcffb94c4a","time":1754795042000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新Facebook案例部分内容"},{"hash":"729de2ee29ddbc24a8dbbc1825e7643d24c425c4","time":1754793150000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(Python-Programming-Course): 完善数据敏感度培养文档内容"},{"hash":"dac5f6473e250277c8fb6860dfb3d5c4ca42c4a7","time":1754792903000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据敏感度培养课程中的量转型内容及示例图"},{"hash":"db3867536d0dc9da8f006b7425d9fbe11bc2f544","time":1754792251000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据思维课程文档中的格式和内容"},{"hash":"1dbe8297f1f0a3be7e96dcf6a15d4c329e1af79f","time":1754785456000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 优化数据敏感性培养文档的格式和可读性"},{"hash":"e09ffc8ad26e3571a52c1cd9500de087c72920f9","time":1754784989000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs(Python-Programming-Course): 更新数据敏感度文档的格式和内容"},{"hash":"a3d91675d849de165e6e2736c4fb173147a2f80c","time":1754783145000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"外面在打雷⛈️，而我在摇晃欲坠中舒展被子……"},{"hash":"af7d38151e88c4653b3179728cb909234ec4275f","time":1754744873000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 在文档中强调\\"数据感\\"的重要性"},{"hash":"3a0b8100ef74ec597b2b369bf0b11da9fb469791","time":1754706534000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 更新数据敏感度培养文档内容"},{"hash":"175ba812327621f3d7f9fa87f79b0efc4f18e43f","time":1754308894000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"docs: 添加数据敏感度培养教程文档"},{"hash":"70353fead4a0a1bfadb60ece94c0f3a9f80bfc08","time":1746926862000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新文件夹名称"},{"hash":"ae8a442bae9aa264fee20e42267291df3a74b667","time":1746879162000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更新食谱文档，优化标签和步骤格式"},{"hash":"9bfdcd8407ca12cf09f385c602eb1c60cc5f3c56","time":1745906987000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"新增 Vuepress 侧边栏自定义文档，包含自动生成侧边栏的说明及相关信息"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":17.58,"words":5274},"filePathRelative":"column/Python-Programming-Course/P06-data_analysis/P06-0-0-Basic-Data-Thinking-Course/02-ruhe-peiyang-shuju-mingandu.md"}`),a={name:`02-ruhe-peiyang-shuju-mingandu.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<figure><img src="/assets/202012011306025306145843-BWHoXwmk.jpeg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你好，我是悦创。</p><p>从这一讲开始，我们进入课程的第一模块——感知数据。整个模块的基本任务，就是培养咱们的<strong>数据感</strong>。这一讲，咱们先说数据感的一个重要方面——<strong>如何提高自己对数据的敏感度？</strong></p><div style="text-align:center;"><p><strong><span style="color:orange;">对一样东西有超乎一般人的敏感度，是思维形成的基础。</span></strong></p></div><p>比如：</p><ul><li>摄影师就对光线有很高的敏感度；</li><li>木工对木头的性质有很高的敏感度。</li></ul><p>但这个能力不是天生的，怎么通过练习提高自己对数据的敏感度呢？这一讲，我来介绍三个方法，分别是<strong>量转型、量定义和对应值</strong>。我们一个一个来说。</p><h2 id="_1-方法一-量转型" tabindex="-1"><a class="header-anchor" href="#_1-方法一-量转型"><span>1. 方法一：量转型</span></a></h2><div style="text-align:center;"><p><strong>量转型不是吹毛求疵，而是让你的思考、沟通和决策更有依据。就像 Facebook 的故事一样，有时候一个小小的数字化思维，可能就是改变世界的第一步。</strong></p></div><p>量，就是数量的量。<strong><span style="color:orange;">量转型的意思就是，你要把过去用定性的方式思考、谈论和使用一个东西的习惯，有意识地转变为用定量的方式思考、谈论和使用。</span></strong></p><p>举个例子：看见一个小姐姐远远地走来，你就不要说，“<strong>小姐姐好漂亮</strong>”，而要说“<strong>小姐姐颜值好高</strong>”。</p><p><strong>为什么呢？</strong></p><ul><li><p>用“漂亮”这个词，就是在用定性的方式思考；「<strong>定性思维</strong>——用一个形容词去描述现象。」</p></li><li><p>而用“颜值”，就是用数量的方式思考。</p></li><li><p>漂亮，只有漂亮和不漂亮两种可能。除了“漂亮”和“不漂亮”，没什么中间状态；</p></li><li><p>而颜值，空间就大了，可以是 10 分制，也可以用百分制。这就是“量转型”。（从模糊到精确，从“好不好”到“多少分”。）</p></li><li><p><strong>举个小例子</strong>：“这个小姐姐颜值很高，大概有 9 分！”</p><p>这里，“颜值”这个词背后就隐含了一个数字化的评价体系：</p><ul><li>可能是 10 分制，也可能是百分制；</li><li>从“漂亮/不漂亮”变成了一个可度量的区间；</li><li>可以精确到 8.3 分、9.5 分，甚至计算平均分。</li></ul></li></ul><p>你是不是想说，这很无聊啊，给女生的容貌打分有这么大的意义吗？你大概不知道大名鼎鼎的 Facebook 的故事吧？Facebook 现在是世界上最重要、规模最大的社交软件，但它起步的时候，就是创始人扎克伯格他们几个男同学想给女同学的颜值打分。没有这一步，就没有现在 Facebook 的成就。</p><p>更重要的是，你要认识到，对数据思维不足的同学来说，数据世界是非常陌生的，数据思维常常很反直觉，这就导致我们对数据的<strong>陌生感、距离感和疏离感，甚至是恐惧感、厌恶感和排斥感</strong>。</p><p>所以，感知数据的第一步就是建立对数据的亲近感。你把量转型看成是游戏也好，思想实验也好，总之，先强迫自己进入数据世界，才有可能领略数据世界的风景。</p><p><strong>思考问题的时候要量转型，社会交往中也要量转型。</strong></p><p>比如，八卦咱们课程的编辑悦创同学的时候，建议你调整自己，不要说“小悦这个人还行”，而要说“我对小悦啊，三七开”。这就从行还是不行这样定性的评价，变成了比例组合的定量评价。</p><p>其实，日常生活里的任何东西，只要你想，就都可以量转型。比如，你买一盏台灯，就不要买只有一个开关的，而是买那种亮度可以调节的。这样，就从“<strong>照亮</strong>”这个概念转型成了“<strong>亮度</strong>”这个定量的概念。</p><p>上面的例子，如果听懂了，接下来则是偏总结的内容。</p><h3 id="_1-1-量转型的本质" tabindex="-1"><a class="header-anchor" href="#_1-1-量转型的本质"><span>1.1 量转型的本质</span></a></h3><ul><li><p><strong>定性</strong>：用描述性的、模糊的、非数字化的语言去表达一个概念或现象。例如：“好漂亮”、“很远”、“很热闹”。</p></li><li><p><strong>定量</strong>：用数字、度量单位、分级体系去刻画现象。例如：“颜值 8.5 分”、“距离 300 米”、“人流量 5000 人”。</p></li><li><p><strong>转型的意义</strong>：</p><ol><li><p><strong>提高精确度</strong>：数字可以让交流更具体，避免歧义。（减少沟通歧义，让大家对“好”有一致的理解。）</p><blockquote><p>如美团点外卖这件事：如果美团外卖只不显示骑手与商家的具体距离，只是告诉你（显示）：骑手距离商家距离很短。</p><p>你告诉我：这个信息对于顾客（你）来说，有用吗？——没用，更何况是急于吃饭的你！是一句没用的信息！</p><p>再来一个例子：美团不显示骑手与你的距离，就显示：骑手马上送达，离你很近。</p><p>你告诉我：这个信息对于顾客（你）来说。有用吗？——没用，没告诉好需要多久就算了，距离也没说！差评！</p><p>只有美团告诉我们：</p><ul><li>骑手与商家的距离；</li><li>骑手与我们的距离；</li><li>骑手送达的预估时间；</li><li>这些信息才是有效信息！</li></ul></blockquote></li><li><p><strong>便于比较</strong>：数字能直接支持排序、筛选、优劣判断。（数字化之后可以排序，比如“班上前五名颜值”。）</p></li><li><p><strong>利于积累与分析</strong>：数字化数据可以被长期保存、趋势分析、可视化展示。（长时间收集数据，可以看趋势，比如“颜值随学期变化”。）</p></li></ol></li></ul><h3 id="_1-2-facebook-案例的深挖" tabindex="-1"><a class="header-anchor" href="#_1-2-facebook-案例的深挖"><span>1.2 Facebook 案例的深挖</span></a></h3><blockquote><p>Facebook 的诞生故事</p></blockquote><ul><li><p><strong>背景</strong>：2003 年，扎克伯格在哈佛读书时，做了一个叫 <strong>Facemash</strong> 的网站，让同学在两个女生的照片中投票，谁更漂亮（其实就是颜值打分+对比）。</p></li><li><p><strong>具体玩法很简单</strong>：</p><ul><li>网站随机展示两位女同学的照片；</li><li>访客点击谁更漂亮；</li><li>系统根据投票计算每位女生的“颜值分”。</li></ul></li><li><p><strong>为什么这是“量转型”</strong>：</p><ul><li><p>如果只是说“这个女生很漂亮”，那是定性判断；</p></li><li><p>如果用投票、打分系统，就把美的程度转成了一个<strong>可排序的数值体系</strong>；</p></li><li><p>通过这个量化系统，扎克伯格抓住了人类的<strong>好奇心</strong>和<strong>比较心理</strong>，获得了用户的强互动。</p></li></ul></li><li><p>注意，这就是量转型的<strong>精髓</strong>：</p><ul><li>如果只是说“她漂亮”，信息到此为止；</li><li>如果把所有人的评价数字化，就可以<strong>排名、比较、统计</strong>；</li><li>一旦可以排名，人类的好奇心和竞争欲就被点燃了。</li></ul></li><li><p><strong>启发</strong>：</p><ul><li><p>从 <strong><span style="color:orange;">模糊</span></strong> 到 <strong><span style="color:orange;">精确</span></strong> ，从“好不好”到“多少分”；</p><blockquote><p>量转型让“好不好”变成了“好到什么程度”；</p></blockquote></li><li><p>数量化的数据可以驱动 <strong><span style="color:orange;">算法推荐、用户匹配、商业化变现</span></strong> ；</p><blockquote><p>数字化之后，信息可以被计算、推荐、商业化；</p></blockquote></li><li><p>即使是看似无聊的打分，也可能成为一个产品的 <strong><span style="color:orange;">核心增长引擎</span></strong>。</p><blockquote><p>这个思路不仅适合科技产品，也适合日常工作和生活。</p></blockquote></li></ul></li></ul><p>结果，这个小网站一夜之间在校园里疯传，访问量大到学校服务器差点宕机。</p><p>后来，扎克伯格改进了这个想法，做成了可以看资料、加好友的社交平台——这，就是 Facebook 的起点。</p><h3 id="_1-3-量转型的普遍应用" tabindex="-1"><a class="header-anchor" href="#_1-3-量转型的普遍应用"><span>1.3 量转型的普遍应用</span></a></h3><p>把 <strong>“漂亮 → 颜值”</strong> 的转变类比到其他场景，你会发现它几乎无处不在：</p><ul><li><p>评价文章 → 文章得分（阅读量、点赞量、完读率）</p><blockquote><p>文章评价 → “写得不错” → <strong>平均阅读完成率 82%</strong></p></blockquote></li><li><p>形容天气 → 温度、湿度、空气质量指数</p><blockquote><p>天气描述 → “今天很热” → <strong>35℃，湿度 80%</strong></p></blockquote></li><li><p>产品体验 → 用户评分（1-5 星）、NPS 指标</p><blockquote><p>销售情况 → “卖得挺好” → <strong>销售额 50 万，环比增长 20%</strong></p></blockquote></li><li><p>销售反馈 → 成交转化率、平均客单价</p></li><li><p>健身状态 → 体脂率、肌肉量、心率变化</p><blockquote><p>健身进度 → “最近瘦了” → <strong>体脂率下降 3%，肌肉量增加 1.5kg</strong></p></blockquote></li></ul><h3 id="_1-4-🎭-情绪-情感的量转型例子「猫头鹰🦉同学研究」" tabindex="-1"><a class="header-anchor" href="#_1-4-🎭-情绪-情感的量转型例子「猫头鹰🦉同学研究」"><span>1.4 🎭 情绪 &amp; 情感的量转型例子「猫头鹰🦉同学研究」</span></a></h3><table><thead><tr><th><strong>定性表达（模糊）</strong></th><th><strong>量化表达（有数字）</strong></th><th><strong>说明</strong></th></tr></thead><tbody><tr><td>今天心情不错</td><td>情绪指数 80/100</td><td>用情绪打分表（Mood Score）衡量当天心情高低</td></tr><tr><td>他很生气</td><td>愤怒值 7/10</td><td>1 表示几乎不生气，10 表示暴走边缘</td></tr><tr><td>她很爱他</td><td>爱意浓度 95%</td><td>通过问卷或行为次数量化亲密度</td></tr><tr><td>有点紧张</td><td>紧张指数 6/10</td><td>比赛前心跳 120 次/分钟，对比平时 75 次</td></tr><tr><td>我很开心</td><td>快乐分 9/10</td><td>通过微笑次数、笑声时长来估算</td></tr><tr><td>他有点焦虑</td><td>焦虑值 5/10</td><td>使用心理量表（如 GAD-7）测量</td></tr><tr><td>很感动</td><td>感动值 8.5/10</td><td>用眼泪次数、心率变化来量化</td></tr><tr><td>她很孤独</td><td>孤独指数 70/100</td><td>根据社交互动次数、独处时间来评估</td></tr><tr><td>有点沮丧</td><td>情绪低谷分 3/10</td><td>定期测量情绪并作趋势分析</td></tr><tr><td>兴奋极了</td><td>兴奋值 9.8/10</td><td>根据语速、手势频率和笑声量化</td></tr></tbody></table><p><strong>可视化效果如下：</strong></p><figure><img src="/assets/%E6%83%85%E7%BB%AA%E7%9A%84%E9%87%8F%E8%BD%AC%E5%9E%8B%E7%A4%BA%E4%BE%8B%E5%9B%BE-CL6f4_zb.png" alt="情绪的量转型示例图" tabindex="0" loading="lazy"><figcaption>情绪的量转型示例图</figcaption></figure><h4 id="_1-4-1-📌-为什么情绪量化有用" tabindex="-1"><a class="header-anchor" href="#_1-4-1-📌-为什么情绪量化有用"><span>1.4.1 📌 为什么情绪量化有用？</span></a></h4><ol><li><p><strong>让感受可比较</strong>：从“我很开心”变成“开心 9 分”，就能看出昨天开心 7 分，今天更高。</p><blockquote><p>比如：</p><ul><li>你跟你的闺蜜说：我今天很开心；</li><li>第二天：你又跟你闺蜜说：我今天很开心；</li><li>闺蜜问：你觉得你哪一天更开心呢？</li><li>你陷入沉思💭：你思索一会之后，脱口而出：我今天比昨天更开心一点。（哎，你发现了吗，你在潜意识中：从很开心「定性」转变到：比昨天更多一点「定量」。）</li></ul><p>所以很多时候，我们学习的目的是把我们无意识的知识，转变成有意识的。——这就是学习。</p><p>生活中很多人其实有意无意的在从：定性转变成定量，但是靠无意识的转变非常缓慢，所以需要刻意学习。</p></blockquote></li><li><p><strong>支持趋势分析</strong>：长期记录情绪分值，可以发现周期规律（比如工作日低、周末高）。</p></li><li><p><strong>减少沟通误差</strong>：不同人对“有点”、“很”这种词理解差异大，数字更统一。</p></li></ol><h4 id="_1-4-2-💡-应用场景" tabindex="-1"><a class="header-anchor" href="#_1-4-2-💡-应用场景"><span>1.4.2 💡 应用场景</span></a></h4><ul><li><strong>心理健康追踪</strong>：每天用 App 打一个“情绪分”，帮助心理师跟踪变化。</li><li><strong>亲密关系管理</strong>：情侣用“幸福指数”打卡，发现感情波动的关键事件。</li><li><strong>团队管理</strong>：项目经理用团队士气分（1-10）来评估工作氛围。</li></ul><h3 id="_1-5-结论" tabindex="-1"><a class="header-anchor" href="#_1-5-结论"><span>1.5 结论</span></a></h3><p>量转型不是“吹毛求疵”，而是把主观印象转化成可记录、可分析的客观指标。Facebook 的故事只是个极端有趣的例子，它说明了——<strong>定量化往往是让一个想法变成可以规模化运作产品的第一步</strong>。</p><h2 id="_2-方法二-量定义" tabindex="-1"><a class="header-anchor" href="#_2-方法二-量定义"><span>2. 方法二：量定义</span></a></h2><div style="text-align:center;"><p><strong><span style="color:orange;">量要准，质才真；定义不清，数据骗人。</span></strong></p></div><p>也就是说：<strong><span style="color:orange;">我们要用量来定义质，从量的方面抓住事物的本质。</span></strong></p><p><strong>这个世界上所有的东西都可以用量来定义</strong>。我再强调一遍，这是数据思维课，不是哲学思辨课，所以对这句话，你不要挑战它，而要适应它。</p><p><strong>举个例子</strong>：你听见小悦说，“我买了一台标准钢琴”，那你就会反应出，小悦买的钢琴有 88 个琴键。只有有 88 个琴键的钢琴才叫标准钢琴。——量定义就是这个意思。</p><p>再比如：海洋酸化。科学家告诉我们，现在的海洋正在酸化。那么，“酸化”到底是什么意思呢？它对应表示的现实世界的情况到底是什么呢？是说海水是酸的吗？</p><p>我们先看看海水现在的酸碱度是多少。一测量，pH 值是 8.1。因为酸碱度的中间位置是 7，比 7 大的都是碱性的，所以现在海水还是碱性的。但是，一百年前是多少呢？8.2 左右。从 8.2 降到 8.1，说明海水正在向酸的方向发展，所以是“酸化”，而不是“酸性”。「所以，当我们加入数值、数据描述后，可以让我们的描述更加准确！」</p><p>再比如：离婚率。我看一个报道说：现在的离婚率高得吓人，刚公布了 2019 年的数据，天津市离婚率最高，排名第一，达到了 71.28%！意思就是说，“每 100 人里面，竟然达到了 71 人离婚的比例。”</p><p>咱们先不要跟着激动，看看离婚率的定义是什么。</p><p>报道给出了图表，说明数据来源是权威的。但是仔细一看，这里的数据是当年的离婚对数和结婚对数之比，意思是说，一年内，如果把所有结婚的看成是 100 对，那么离婚的相应就有 71 对。但是请注意，离婚的这些对，并不都是当年结婚的呀。也许会有那么几对是当年结、当年离，但这样的情况比较少，大部分都是往年结的。所以，分子和分母对应的不是一群人，“每 100 人就有 71 人离婚”这样的推论当然就是大错特错的。</p><p>如果真的想知道每 100 个人里有多少离婚，该怎么做呢？</p><p>就要把同一批结婚的人找出来，然后跟踪。比如 2020 年结婚的都记录下来，到 2023 年看一下，这批人里有多少离婚了，我们就知道了 3 年内的离婚率。还是这批人，到了 2027 年，再看一下有多少人离婚，就能判断“七年之痒”这个说法该不该重视。</p><p><strong>简单总结一下：</strong></p><p>这里说的“量定义”，是为了让你理解事物在质和量上的关系。<strong><span style="color:orange;">我们一定可以找到一个关键量，这个量抓住了事物的本质，使这个事物得以与其他事物区别开来。这个信念就是数据思维最基本的认知之一。</span></strong></p><p>但是回到现实世界，我们会面临一个具体问题：有些概念在观念世界里很清楚，但是要在现实世界里抓住它、看到它，就需要一个重要的方法，用量来定义这个概念。这就是“量定义”的高级阶段。你知道，在现实世界，我们就是用测量的方式，逼进一个观念世界里的概念的。</p><p>举个例子，说一个人老了，那含义很清楚，60 岁以上就是老了。这里说的是生理年龄，不是心态，也不是活力等。但是说一个社会老了，怎么定义呢？一个社会，生生不息，怎么确定标准呢？</p><p>这就需要一个像生理年龄一样的标准去测量它。因此，我们就把老年人口占全体人口的比例看成是测量一个社会“生理上”老化程度的指标。刚才我们说了，定义一个老年人的标准是 60 岁以上，那么老年人口就是所有 60 岁及以上的群体。这样一来，通过老年人口占全体人口的比例，我们就能测量一个社会的老化程度了。</p><blockquote><p><strong>补充</strong>：</p><ol><li><strong>让你意识到，定义一个事物时必须用可量化、精确对应现实的指标，而不是模糊印象</strong><ul><li>“天津市离婚率 71.28%”乍听很惊人，但如果不搞清楚统计口径（分子分母是否对应同一批人），就会得出错误的理解。</li><li>这个案例提醒我们，数据里的“量”必须定义清楚，否则数字看似精确，含义却可能完全错位。</li></ul></li><li><strong>展示“质”是如何由“量”来刻画的</strong><ul><li>离婚率这个“质的特征”（离婚情况）要通过一个正确、合理的“量”去定义（比如跟踪同一批人的离婚情况）。</li><li>如果量的定义错了，就不能正确反映质的本质特征。</li></ul></li></ol><p>简单来说，这个“离婚率”的故事是在告诉你：<strong>数据思维不仅是用数字描述，还要先确保“数字的定义”正确且与所研究的对象严丝合缝</strong>，否则得出的结论就是假象。</p></blockquote><h2 id="_3-方法三-对应值" tabindex="-1"><a class="header-anchor" href="#_3-方法三-对应值"><span>3. 方法三：对应值</span></a></h2><p>接着社会的老龄化问题。量定义清楚了，使用老年人口占全体人口的比例来测量。那么，这个比例要达到多少才是一个老龄社会呢？</p><p>这里，对应值就出场了。根据人口学家的共识，老年人口，也就是 60 岁以上的人口所占的比例超过 10%，就是老龄社会。这个 10% 就是对应值。</p><p>老龄社会的对应值比较有共识，但是还有很多情况，对应值并没有共识，需要你来研究确定。</p><p>比如，讨论科研领域的性别平等状况，中国是平等的，还是不平等的呢？</p><p>性别平等状况的量定义比较清楚，把所有的科学家看成是 100 人，计算女性科学家在其中所占的比例就可以了。但是，哪个比例对应性别平等，哪个比例对应性别不平等呢？</p><p>这个对应值就很难有共识。有人说，女性科学家必须占 50% 及以上，才是平等的。也有人说，40% 及以上就可以。还有的人说，在纯自然科学领域，超过 30% 就算平等，因为女性对探讨大自然兴趣不大，30% 就说明没有社会障碍了。</p><p>到底谁的对应值是对的呢？这里我们不讨论，我们是数据思维课，不是社会学通识课。我只是通过这个例子让你明白，<strong><span style="color:orange;">在很多情景下，对应值反映的是你对事物性质和原因的理解，理解不同，选择的值就可能不一样。但从数据思维的角度来说，你必须确定一个对应值，才能定义清楚你对事物的理解。</span></strong></p><p>有了对应值这个概念，我们就开辟了一个思考问题的新角度。</p><p>举个例子，什么是微笑呢？你就不一定非从心理上定义，而是可以找到一个量来定义它。比如，露出三分之一的牙，在观察者看来就是微笑。</p><p>这个方式就是银行、证监会、支付宝和微信支付等金融机构监控异常情况的逻辑。通过记录客户行为，形成一个客户支付行为的模式。这样，设计者就能找到一个对应值，在这个对应值以内，就是正常的；超过这个对应值，系统就会报警，认为这个客户有异常。</p><blockquote><p>提高了对数据的敏感度之后，下一讲我们再前进一步，看看在工作和生活中面对具体的数据时，该如何感知它们的意义。</p><p>我是悦创，我们下一讲再见。</p></blockquote><blockquote><p>如何通过练习提高自己对数据的敏感度呢？教你三个方法——</p><p>一，量转型。思考、谈论和使用一个东西时，有意识地把过去定性的方式转变为定量的方式。</p><p>二，量定义。如果一个事物的性质是用某一方面的量来定义的，就搞清楚它具体是怎么定义的。</p><p>三，对应值。在量定义的基础上，为事物确定一个明确的量的标准。</p></blockquote><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,74)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};